85: /** All 7 modalities available in the system. */
86: const ALL_MODALITIES: Modality[] = [
87:   'Deterministic', 'Strategic', 'Embodied',
88:   'ScenarioChoice', 'LanguageReflective', 'SocialCooperative', 'ImmersiveRPG',
89: ];
90: 
91: /** Ponytail: task-type sets per modality — modalities whose preferred chain has no match in the module won't be assigned. */
92: const MODALITY_TASK_TYPES: Record<Modality, readonly string[]> = {
93:   Deterministic: ['n_back', 'stroop', 'go_no_go', 'reaction_time'],
94:   Strategic: ['pattern_prediction'],
95:   Embodied: ['hold', 'reaction_time'],
96:   ScenarioChoice: ['dilemma', 'scenario'],
97:   LanguageReflective: ['self_report', 'llm_dialogue'],
98:   SocialCooperative: ['cooperation', 'imitation'],
99:   ImmersiveRPG: ['dilemma', 'scenario', 'emotion_identification', 'self_report', 'cooperation'],
100: };
