102: /** Modalities that require specific session conditions. */
103: const ENERGY_GATED: Modality[] = ['Embodied'];
104: const TIME_GATED: Modality[] = ['Strategic'];
105: 
106: /**
107:  * Generate all eligible encounter candidates given current significator and world state.
108:  * Applies 5 filters: layer-perception, altitude, cooldown, narrative gate, modality availability.
109:  */
110: export function generateCandidates(
111:   sig: Significator,
112:   world: WorldState,
113:   now: number,
114:   session?: SessionContext,
115: ): EncounterCandidate[] {
116:   const maxStageOrd = stageOrdinal(sig.currentStage) + 1;
117:   const candidates: EncounterCandidate[] = [];
118:   const recent = world.recentEncounters ?? [];
119: 
120:   // Filter 5: Determine blocked modalities based on session context
121:   const blockedModalities = new Set<Modality>();
122:   if (session?.inferredEnergy === 'low') {
123:     ENERGY_GATED.forEach(m => blockedModalities.add(m));
124:   }
125:   if (session?.estimatedTimeAvailable !== undefined && session.estimatedTimeAvailable < 900000) {
126:     TIME_GATED.forEach(m => blockedModalities.add(m));
127:   }
128: 
129:   // Compute macro-event modifications from active events
130:   const macroModifications = computeMacroModifications(world);
131: 
132:   for (const holon of world.holons) {
133:     if (!holon.active) continue;
134: 
135:     // If forceLine is provided, filter candidates to only matching holon.line.
136:     if (session?.forceLine && holon.line !== session.forceLine) continue;
137: 
138:     // If forceStage is provided, filter candidates to only matching holon.stage.
139:     if (session?.forceStage && holon.stage !== session.forceStage) continue;
140: 
141:     const bypassChecks = !!(session?.forceLine || session?.forceStage);
142: 
143:     if (!bypassChecks) {
144:       // Filter 1: Layer-perception (stage <= current + 1)
145:       if (stageOrdinal(holon.stage) > maxStageOrd) continue;
146: 
147:       // Filter 2: Altitude requirement (stage <= line altitude + 1)
148:       const lineAltOrd = stageOrdinal(sig.altitudes[holon.line]);
149:       if (stageOrdinal(holon.stage) > lineAltOrd + 1) continue;
150:     }
151: 
152:     const moduleRef = `${holon.line}:${holon.stage}`;
153: 
154:     // Generate candidates across eligible modalities (2-3 per holon)
155:     const eligible = session?.forceModality
156:       ? [session.forceModality as Modality]
157:       : getEligibleModalities(holon, blockedModalities);
158: 
159:     const anyForcing = !!(session?.forceLine || session?.forceStage || session?.forceModality);
160: 
161:     for (const modality of eligible) {
162:       if (!anyForcing) {
163:         // Filter 3: Cooldown — timestamp-based
164:         const tupleKey = `${holon.line}:${holon.stage}:${modality}`;
165:         const cooldownTs = world.cooldowns[tupleKey] ?? world.cooldowns[moduleRef] ?? 0;
