217: function getEligibleModalities(
218:   holon: Holon,
219:   blocked: Set<Modality>,
220:   moduleTaskTypes?: Set<string>,
221: ): Modality[] {
222:   const primary = holon.modality ?? 'ImmersiveRPG';
223:   
224:   // Filter modalities to only those whose preferred chain has ≥1 match in the module
225:   const taskTypes = moduleTaskTypes ?? getAllTaskTypes();
226:   const eligible = ALL_MODALITIES.filter(m => {
227:     if (blocked.has(m)) return false;
228:     const chain = MODALITY_TASK_TYPES[m];
229:     return chain.some(t => taskTypes.has(t));
