206:   const candidateDrive = holon?.drives.dominant ?? null;
207:   if (!candidateDrive) return 0;
208: 
209:   return candidateDrive === DRIVE_COMPLEMENT[maxDrive] ? maxVal : 0;
210: }
211: 
212: /**
213:  * §3.2.6 — Active narrative beat match → 1.0.
214:  * Else if holon has existing relationship → 0.4 (static or dynamic). Else 0.
215:  */
216: function computeNarrativeCoherence(c: EncounterCandidate, world: WorldState): number {
217:   const holon = world.holons.find(h => h.id === c.holonId);
218:   if (!holon) return 0;
219: 
220:   // Check dynamic NPC relationships from ConsequenceEngine
221:   const dynamicRel = world.npcRelationships?.find(r => r.holonId === c.holonId);
222:   if (dynamicRel && dynamicRel.strength > 0.3) return 0.4;
223: 
224:   // Fall back to static holon relationship data
225:   if (holon.relationships.length > 0) return 0.4;
226:   return 0;
227: }
228: 
229: /**
230:  * §3.2.7 — Three sub-scores averaged:
231:  * Duration: short+short → 0.4, long+long → 0.2, else 0.1
232:  * Energy: low+low → 0.3, high+high → 0.3, mismatch → 0
233:  * Modality preference: 0.3 * (preference score, default 0.5)
234:  */
235: function computeSessionFit(c: EncounterCandidate, session: SessionContext): number {
236:   // Duration sub-score
237:   const shortSession = (session.estimatedTimeAvailable ?? session.sessionDurationMs) < 900_000; // < 15min
238:   const shortEncounter = c.modality === 'Deterministic' || c.modality === 'Embodied';
239:   const longEncounter = c.modality === 'ImmersiveRPG' || c.modality === 'SocialCooperative';
240:   let duration: number;
241:   if (shortSession && shortEncounter) duration = 0.4;
242:   else if (!shortSession && longEncounter) duration = 0.2;
243:   else duration = 0.1;
244: 
245:   // Energy sub-score
246:   const energy = session.inferredEnergy ?? 'moderate';
247:   const highIntensity = c.modality === 'ImmersiveRPG' || c.modality === 'Strategic';
248:   const lowIntensity = c.modality === 'LanguageReflective' || c.modality === 'ScenarioChoice';
249:   let energyScore: number;
250:   if (energy === 'low' && lowIntensity) energyScore = 0.3;
251:   else if (energy === 'high' && highIntensity) energyScore = 0.3;
252:   else if (energy === 'moderate') energyScore = 0.15;
253:   else energyScore = 0;
254: 
255:   // Modality preference sub-score (no preference data available, use default 0.5)
256:   const modalityPref = 0.3 * 0.5;
257: 
258:   return (duration + energyScore + modalityPref) / 3;
259: }

