321:       const { generateShadowContent, buildShadowPromptSuffix } = await import('../engines/ShadowContentGenerator.js');
322:       const shadowContent = generateShadowContent(shadowLine, shadowStage, this.encounter.shadowTarget);
323:       
324:       const unresolvedShadows = this.significator.shadows.entries.filter(
325:         (e: { line: string; resolvedAt: number | null }) => e.line === shadowLine && e.resolvedAt === null
326:       ).length;
327:       
328:       shadowContext = buildShadowPromptSuffix(shadowContent, shadowLine, shadowStage, unresolvedShadows);
329:     }
330: 
331:     const systemPrompt = `${context.systemPrompt}${assessmentContext}${continuityContext}${shadowContext}
332: [AGENT RULES]
333: 1. You are the Agentic Game Master driving this developmental encounter.
334: 2. Present the encounter situationally and narratively. If you need to present stimuli, choices, or ask questions, ALWAYS call the 'ask_user_question' tool. Do not ask questions in raw text responses.
