465: // ── Pattern Prediction Renderer ──────────────────────────────────────
466: 
467: export function renderPatternPrediction(task: AssessmentTask): {
468:   prompt: AskUserQuestionParams;
469:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
470: } {
471:   const diff = getDifficulty(task.parameters.stage as string | undefined);
472:   const disks = (task.parameters.disks as number) ?? diff.patternDisks;
473:   const attempts = (task.parameters.attempts as number) ?? diff.patternAttempts;
474: 
475:   const base = Math.floor(Math.random() * 5) + 1;
476:   const step = Math.floor(Math.random() * 3) + 1;
477:   const pattern = Array.from({ length: 4 }, (_, i) => base + step * i);
478:   const nextValue = pattern[3]! + step;
479: 
480:   const question = [
481:     `Observe the pattern of ${disks} elements across ${attempts} steps:`,
482:     ``,
483:     `  ${pattern.map((v, i) => `${C.dim}Step ${i + 1}:${C.reset} ${'█'.repeat(v)} ${v}`).join('\n  ')}`,
484:     ``,
485:     `${C.bold}What is Step 5?${C.reset}`,
486:   ].join('\n');
487: 
488:   const options: DriveOption[] = [
489:     { label: `${nextValue}`, description: `The next value (increasing by ${step})`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
490:     { label: `${nextValue + step}`, description: `Larger step`, drive: 'communion', polarity: 'neutral', correctnessScore: 0.3 },
491:     { label: `${nextValue - 1}`, description: `Close but not quite`, drive: 'eros', polarity: 'neutral', correctnessScore: 0.5 },
492:     { label: `No pattern`, description: 'I see no clear pattern', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
493:   ];
494:   shuffle(options);
495: 
496:   return {
497:     prompt: {
498:       questions: [{
499:         question,
500:         header: 'Pattern Recognition',
501:         options: options.map(o => ({ label: o.label, description: o.description })),
502:         allowWriteIn: true,
503:         multiSelect: false,
504:       }],
505:     },
506:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
507:       const durationMs = endTimeMs - startTimeMs;
508:       const numericMatch = answer.match(/\d+/);
509:       const playerValue = numericMatch ? parseInt(numericMatch[0]!, 10) : -1;
510: 
511:       const error = Math.abs(playerValue - nextValue);
512:       const accuracy = Math.max(0, 1 - error / Math.max(1, disks));
513: 
514:       const expectedTime = attempts * 3000;
515:       const timeRatio = durationMs / expectedTime;
516:       const responseTime = timeRatio < 0.5 ? 0.9 : timeRatio < 1.5 ? 0.7 : timeRatio < 3 ? 0.5 : 0.3;
517: 
518:       const matchedOpt = options.find(o => answer.includes(o.label));
519: 
520:       return {
521:         taskId: task.id,
522:         timestamp: startTimeMs,
523:         dimensions: {
524:           accuracy,
525:           response_time: responseTime,
526:           complexity_handled: accuracy,
527:           self_correction: error <= 1 ? 0.8 : 0.4,
528:         },
529:         rawResponse: {
530:           pattern, nextValue, playerValue, step,
531:           matchedDrive: matchedOpt?.drive ?? null,
532:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
533:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
534:         },
535:         durationMs,
536:       };
537:     },
538:   };
539: }
