2:  * ProfileUpdater — the runtime loop that updates Significator after encounters.
3:  * encounter result → altitude → stage → rays → shadows → drives
4:  */
5: import type { Drive } from '../domain/Drive.js';
6: import type { Line } from '../domain/Line.js';
7: import { LINE_QUADRANT } from '../domain/Line.js';
8: import type { Significator, DriveState } from '../domain/Significator.js';
9: import type { TaskSlug } from '../domain/SharedTypes.js';
10: import type { ShadowQuadrant } from '../domain/enums.js';
11: import { stageOrdinal } from '../domain/Stage.js';
12: import { thresholdToStage } from './ThresholdMaps.js';
13: import { capToCeiling } from './LineCeilings.js';
14: import { computeRayProfile } from './RayProfileComputer.js';
15: import { synthesiseStage } from './StageSynthesizer.js';
16: import { detectShadows } from './ShadowDetector.js';
17: import type { ShadowLedger } from '../domain/ShadowLedger.js';
18: 
19: /** Result of a single encounter's cognitive task. */
20: export interface EncounterResult {
21:   readonly line: Line;
22:   readonly taskSlug: TaskSlug;
23:   readonly trials: readonly { correct: boolean }[];
24:   /** Optional: which drive the player's choices leaned toward. */
25:   readonly driveChoice?: Drive;
26: }
27: 
28: const QUADRANT_TO_DRIVE: Record<string, Drive> = {
29:   UR: 'Agency',
30:   UL: 'Eros',
31:   LL: 'Communion',
32:   LR: 'Agape',
33: };
34: 
35: export function driveForLine(line: Line): Drive {
36:   return QUADRANT_TO_DRIVE[LINE_QUADRANT[line]] ?? 'Agency';
37: }
38: 
39: const SIGNAL_TO_QUADRANT: Record<string, ShadowQuadrant> = {
40:   fixation: 'DarkAddiction',
41:   regression: 'DarkAllergy',
42:   repression: 'GoldenAddiction',
43: };
44: 
45: /**
46:  * Update the Significator after an encounter.
47:  * Returns a new immutable Significator (no mutation).
48:  */
49: export function updateProfile(sig: Significator, result: EncounterResult): Significator {
50:   // 1. Map trial accuracy → proposed altitude for the line
51:   const correctCount = result.trials.filter(t => t.correct).length;
52:   const threshold = result.trials.length > 0 ? Math.round((correctCount / result.trials.length) * 10) : 1;
53:   const proposedStage = thresholdToStage(result.line, threshold);
54: 
55:   // 2. Enforce line ceiling
56:   const currentAltitudes = { ...sig.altitudes };
57:   const capped = capToCeiling(result.line, proposedStage, currentAltitudes);
58: 
59:   // Only advance (never regress from encounter alone)
60:   const currentOrd = stageOrdinal(currentAltitudes[result.line]);
61:   const cappedOrd = stageOrdinal(capped);
62:   if (cappedOrd > currentOrd) {
63:     currentAltitudes[result.line] = capped;
64:   }
65: 
66:   // 3. Recompute synthesised stage
67:   const newStage = synthesiseStage(currentAltitudes);
68: 
69:   // 4. Recompute ray profile
70:   const newRayProfile = computeRayProfile(currentAltitudes);
71: 
72:   // 5. Update drive fixation risk
73:   const newDrives = updateDriveRisk(sig.drives, result.driveChoice);
74: 
75:   // 6. Build updated Significator for shadow detection
76:   const updated: Significator = {
77:     ...sig,
78:     altitudes: currentAltitudes,
79:     currentStage: newStage,
80:     rayProfile: newRayProfile,
81:     drives: newDrives,
82:     totalEncounters: sig.totalEncounters + 1,
83:   };
84: 
85:   // 7. Detect shadows and surface new entries
86:   const signals = detectShadows(updated);
87:   const now = Date.now();
88:   const existingEntries = [...sig.shadows.entries];
89:   for (const signal of signals) {
90:     const alreadyTracked = existingEntries.some(
91:       e => e.line === signal.line && e.resolvedAt === null,
92:     );
93:     if (!alreadyTracked) {
94:       existingEntries.push({
95:         id: `shadow-${now}-${signal.line}`,
96:         quadrant: SIGNAL_TO_QUADRANT[signal.type] ?? 'DarkAddiction',
97:         line: signal.line,
98:         stage: currentAltitudes[signal.line],
99:         drive: driveForLine(signal.line),
100:         surfacedAt: now,
101:         resolvedAt: null,
102:         recurrenceCount: 0,
103:         compoundPartner: null,
104:         severity: 1,
105:       });
106:     }
107:   }
108:   const newShadows: ShadowLedger = {
109:     entries: existingEntries,
110:     activeCount: existingEntries.filter(e => e.resolvedAt === null).length,
111:   };
112: 
113:   return { ...updated, shadows: newShadows };
114: }
115: 
116: /**
117:  * Update drive fixation risk based on choice patterns.
118:  */
119: function updateDriveRisk(drives: DriveState, choice?: Drive): DriveState {
120:   if (!choice) return drives;
121: 
122:   const decay = 0.95;
123:   const boost = 0.1;
124: 
125:   const newRisk = { ...drives.fixationRisk };
126:   for (const d of Object.keys(newRisk) as Drive[]) {
127:     newRisk[d] = newRisk[d] * decay;
128:   }
129:   newRisk[choice] = Math.min(1, newRisk[choice] + boost);
130: 
131:   return { weights: drives.weights, fixationRisk: newRisk };
132: }

