137:   driveHealth: DriveHealthInput;
138:   polarity: PolarityInput;
139:   shadowTopology: ShadowTopologyInput;
140:   transformationReadiness: TransformationReadinessInput;
141: }
142: 
143: // ---------------------------------------------------------------------------
144: // Dimension extraction from SignificatorSnapshot
145: // ---------------------------------------------------------------------------
146: 
147: function extractDimensionInputs(sig: SignificatorSnapshot): CCIDimensionInputs {
148:   return {
149:     altitude: extractAltitudeInput(sig),
150:     driveHealth: extractDriveHealthInput(sig),
151:     polarity: extractPolarityInput(sig),
152:     shadowTopology: extractShadowTopologyInput(sig),
153:     transformationReadiness: extractTransformationReadinessInput(sig),
154:   };
155: }
156: 
157: function extractAltitudeInput(sig: SignificatorSnapshot): AltitudeInput {
158:   const ordinals = ALL_LINES.map(l => stageOrdinal(sig.altitudes[l]));
159:   const mean = ordinals.reduce((a, b) => a + b, 0) / ordinals.length;
160:   const variance = ordinals.reduce((sum, o) => sum + (o - mean) ** 2, 0) / ordinals.length;
161:   // Normalise spread to 0-1 range (max possible stddev is ~3.5 for 8 stages)
162:   const spread = Math.sqrt(variance) / 3.5;
163: 
164:   const lowestOrdinal = Math.min(...ordinals);
165:   const highestOrdinal = Math.max(...ordinals);
166: 
167:   const ALL_STAGES: readonly Stage[] = [
168:     'Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White',
169:   ];
170:   const lowestAltitude = ALL_STAGES[lowestOrdinal] as Stage;
171:   const highestAltitude = ALL_STAGES[highestOrdinal] as Stage;
172: 
173:   // Lines at edge: lines at or above current stage (growth edge contributors)
174:   const currentOrdinal = stageOrdinal(sig.currentStage);
175:   const linesAtEdge = ordinals.filter(o => o >= currentOrdinal).length;
176: 
177:   return {
178:     perLineAltitudes: sig.altitudes as Record<Line, Stage>,
179:     centreOfGravity: sig.currentStage,
180:     spread: Math.min(1.0, spread),
181:     lowestAltitude,
182:     highestAltitude,
183:     linesAtEdge,
184:   };
185: }
186: 
187: function extractDriveHealthInput(sig: SignificatorSnapshot): DriveHealthInput {
188:   const balance = sig.driveBalance;
189:   const fixationRisk = sig.fixationRisk;
190: 
191:   const maxImbalance = Math.max(...ALL_DRIVES.map(d => Math.abs(balance[d])));
192:   const maxFixationRisk = Math.max(...ALL_DRIVES.map(d => fixationRisk[d]));
193: 
194:   // Complementary tension: |Agency - Communion| and |Eros - Agape|
195:   const agencyVsCommunion = Math.abs(balance['Agency'] - balance['Communion']);
196:   const erosVsAgape = Math.abs(balance['Eros'] - balance['Agape']);
197: 
198:   // Normalise tension to 0-1 (max possible is 2.0 for balance range -1..1)
199:   const complementaryTension = {
200:     agencyVsCommunion: Math.min(1.0, agencyVsCommunion / 2.0),
201:     erosVsAgape: Math.min(1.0, erosVsAgape / 2.0),
202:   };
203: 
204:   return {
205:     balance,
206:     fixationRisk,
207:     maxImbalance: Math.min(1.0, maxImbalance),
208:     maxFixationRisk: Math.min(1.0, maxFixationRisk),
209:     complementaryTension,
210:   };
211: }
212: 
213: function extractPolarityInput(sig: SignificatorSnapshot): PolarityInput {
214:   const master = sig.polarity.master;
215: 
216:   // Map PolarityMode to the spec's lowercase mode naming
217:   let masterMode: 'exploration' | 'crystallizing' | 'crystallized';
218:   switch (master.mode) {
219:     case 'Exploring':
220:       masterMode = 'exploration';
221:       break;
222:     case 'Crystallizing':
223:       masterMode = 'crystallizing';
224:       break;
225:     case 'Crystallized':
226:       masterMode = 'crystallized';
227:       break;
228:     default:
229:       masterMode = 'exploration';
230:   }
231: 
232:   // Exploratory breadth: diversity of polarity cell patterns sampled
233:   // Computed from the number of distinct non-null patterns across cells
234:   const cells = Object.values(sig.polarity.cells);
235:   const distinctPatterns = new Set(cells.map(c => c.dominantPattern).filter(Boolean));
236:   const exploratoryBreadth = cells.length > 0
237:     ? Math.min(1.0, distinctPatterns.size / 4) // 4 energetic directions = max diversity
238:     : 0;
239: 
240:   // Recent polarity stability: coherence of recent traces
241:   // Approximated from average coherence of cells
242:   const avgCoherence = cells.length > 0
243:     ? cells.reduce((sum, c) => sum + c.coherence, 0) / cells.length
244:     : 0;
245: 
246:   return {
247:     masterMode,
248:     crystallizationIndex: master.crystallizationProgress,
249:     exploratoryBreadth,
250:     coherentLineCount: master.coherentLineCount,
251:     recentPolarityStability: avgCoherence,
252:   };
253: }
254: 
255: function extractShadowTopologyInput(sig: SignificatorSnapshot): ShadowTopologyInput {
256:   const entries = sig.shadows.entries;
257:   const unresolved = entries.filter(e => e.resolvedAt === null);
258:   const resolved = entries.filter(e => e.resolvedAt !== null);
259: 
260:   const unresolvedCount = unresolved.length;
261:   const averageSeverity = unresolvedCount > 0
262:     ? unresolved.reduce((sum, e) => sum + e.severity, 0) / unresolvedCount
263:     : 0;
264:   const maxSeverity = unresolvedCount > 0
265:     ? Math.max(...unresolved.map(e => e.severity))
266:     : 0;
267: 
268:   const compoundPatternCount = sig.compoundShadows.length;
269: 
270:   // Recent surfacing rate: approximated from total entries / total sessions
271:   const recentSurfacingRate = sig.totalSessions > 0
272:     ? entries.length / sig.totalSessions
273:     : 0;
274: 
275:   // Integration rate: resolved per session
276:   const integrationRate = sig.totalSessions > 0
277:     ? resolved.length / sig.totalSessions
278:     : 0;
279: 
280:   // Oldest unresolved age: sessions since creation proxy
281:   // Use totalSessions minus an estimate based on entry index
282:   const oldestUnresolvedAge = unresolvedCount > 0
283:     ? sig.totalSessions // Conservative: oldest could have been there since start
284:     : 0;
285: 
286:   return {
287:     unresolvedCount,
288:     averageSeverity,
289:     maxSeverity,
290:     compoundPatternCount,
291:     recentSurfacingRate: Math.max(recentSurfacingRate, 0.001), // avoid division by zero
292:     integrationRate,
293:     oldestUnresolvedAge,
294:   };
295: }
296: 
297: function extractTransformationReadinessInput(sig: SignificatorSnapshot): TransformationReadinessInput {
298:   const tr = sig.transformationReadiness;
299:   return {
300:     linesAtEdge: tr.linesAtEdge,
301:     shadowClearance: tr.shadowClearance,
302:     catalystSaturation: tr.catalystSaturation,
303:     pendingTransformation: tr.pendingTransformation,
304:     targetStage: tr.targetStage,
305:     sessionsSinceLastTransformation: tr.sessionsSinceLastTransformation,
306:   };
307: }
308: 
309: // ---------------------------------------------------------------------------
310: // Normalisation functions (each returns 0.0 to 1.0)
311: // ---------------------------------------------------------------------------
312: 
313: /**
314:  * Normalise altitude dimension.
315:  * Centre of gravity is primary signal, with holonic penalty (floor too far
316:  * below CoG) and spread penalty (uneven development).
317:  */
318: export function normaliseAltitude(input: AltitudeInput): number {
319:   const cogValue = stageOrdinal(input.centreOfGravity) / 7;
320:   const floorValue = stageOrdinal(input.lowestAltitude) / 7;
321: 
322:   // Holonic health: floor pulls the effective altitude down when gap > 2 stages
323:   const holonicPenalty = Math.max(0, cogValue - floorValue - (2 / 7)) * 0.3;
324: 
325:   // Spread penalty: highly uneven development reduces effective altitude
326:   const spreadPenalty = input.spread * 0.15;
327: 
328:   return clamp(cogValue - holonicPenalty - spreadPenalty);
329: }
330: 
331: /**
332:  * Normalise drive health dimension.
333:  * INVERTED: high score = healthy (low imbalance, low fixation).
334:  * Combines balance health, fixation health, and complementary tension health.
335:  */
336: export function normaliseDriveHealth(input: DriveHealthInput): number {
337:   const balanceHealth = 1.0 - input.maxImbalance;
338:   const fixationHealth = 1.0 - input.maxFixationRisk;
339:   const tensionHealth = 1.0 - (
340:     input.complementaryTension.agencyVsCommunion * 0.5 +
341:     input.complementaryTension.erosVsAgape * 0.5
342:   );
343: 
344:   return clamp(
345:     balanceHealth * 0.35 +
346:     fixationHealth * 0.40 +
347:     tensionHealth * 0.25
348:   );
349: }
350: 
351: /**
352:  * Normalise polarity dimension.
353:  * Reflects CLARITY of polarity direction, not which direction.
354:  * Exploration rewards breadth, crystallizing rewards emerging coherence,
355:  * crystallized rewards stability.
356:  */
357: export function normalisePolarity(input: PolarityInput): number {
358:   switch (input.masterMode) {
359:     case 'exploration':
360:       // In exploration, score reflects breadth of sampling
361:       return clamp(input.exploratoryBreadth * 0.4);
362:     case 'crystallizing':
363:       // In crystallizing, score reflects emerging coherence
364:       return clamp(0.4 + (input.crystallizationIndex * 0.3));
365:     case 'crystallized':
366:       // In crystallized, score reflects depth and stability
367:       return clamp(0.7 + (input.recentPolarityStability * 0.3));
368:   }
369: }
370: 
371: /**
372:  * Normalise shadow topology dimension.
373:  * INVERTED: high score = clean (few shadows, well-integrated).
374:  * Penalises unresolved count, max severity, compound patterns, stale age,
375:  * and poor integration rate relative to surfacing.
376:  */
377: export function normaliseShadowTopology(input: ShadowTopologyInput): number {
378:   const countPenalty = Math.min(input.unresolvedCount / 12, 1.0);
379:   const severityPenalty = input.maxSeverity;
380:   const compoundPenalty = Math.min(input.compoundPatternCount / 4, 1.0);
381:   const stalePenalty = Math.min(input.oldestUnresolvedAge / 20, 1.0);
382: 
383:   // Integration credit: ratio of integration to surfacing, capped at 1.0
384:   const integrationCredit = input.recentSurfacingRate > 0
385:     ? Math.min(input.integrationRate / input.recentSurfacingRate, 1.0)
386:     : 0;
387: 
388:   const rawPenalty = (
389:     countPenalty * 0.25 +
390:     severityPenalty * 0.30 +
391:     compoundPenalty * 0.20 +
392:     stalePenalty * 0.15 +
393:     (1.0 - integrationCredit) * 0.10
394:   );
395: 
396:   return clamp(1.0 - rawPenalty);
397: }
398: 
399: /**
400:  * Normalise transformation readiness dimension.
401:  * Active transformation saturates at 1.0. No target returns 0.0.
402:  * Otherwise: edgeProgress * clearanceFactor * saturation * recoveryDamping.
403:  */
404: export function normaliseTransformationReadiness(input: TransformationReadinessInput): number {
405:   if (input.pendingTransformation) return 1.0;
406:   if (!input.targetStage) return 0.0;
407: 
408:   const edgeProgress = Math.min(input.linesAtEdge / 6, 1.0);
409:   const clearanceFactor = input.shadowClearance ? 1.0 : 0.6;
410:   const saturationFactor = input.catalystSaturation;
411: 
412:   // Post-transformation recovery: reduce readiness signal for 5 sessions
413:   const recoveryDamping = input.sessionsSinceLastTransformation < 5
414:     ? input.sessionsSinceLastTransformation / 5
415:     : 1.0;
416: 
417:   return clamp(edgeProgress * clearanceFactor * saturationFactor * recoveryDamping);
418: }
419: 
420: // ---------------------------------------------------------------------------
421: // Weight adjustment
422: // ---------------------------------------------------------------------------
423: 
424: /**
425:  * Context-sensitive weight adjustment. Weights shift based on the
426:  * Significator's current developmental state to ensure proportional
427:  * response to the most urgent developmental need.
428:  */
429: export function adjustWeights(
430:   defaults: CCIWeights,
431:   inputs: CCIDimensionInputs,
432: ): CCIWeights {
433:   // Active transformation override: hardcoded weights for transformation mode
434:   if (inputs.transformationReadiness.pendingTransformation) {
435:     return {
436:       altitude: 0.05,
437:       driveHealth: 0.10,
438:       polarity: 0.05,
439:       shadowTopology: 0.10,
440:       transformationReadiness: 0.70,
441:     };
442:   }
443: 
444:   const adjusted = { ...defaults };
445: 
446:   // Near-transformation: boost TR, reduce altitude and polarity
447:   if (inputs.transformationReadiness.linesAtEdge >= 4) {
448:     adjusted.transformationReadiness += 0.10;
449:     adjusted.altitude -= 0.05;
450:     adjusted.polarity -= 0.05;
451:   }
452: 
453:   // Heavy shadow load: boost shadow, reduce transformation readiness
454:   if (inputs.shadowTopology.unresolvedCount > 8 || inputs.shadowTopology.maxSeverity > 0.7) {
455:     adjusted.shadowTopology += 0.10;
456:     adjusted.transformationReadiness -= 0.10;
457:   }
458: 
459:   // Severe drive imbalance: boost drive health, reduce polarity and altitude
460:   if (inputs.driveHealth.maxFixationRisk > 0.7) {
461:     adjusted.driveHealth += 0.10;
462:     adjusted.polarity -= 0.05;
463:     adjusted.altitude -= 0.05;
464:   }
465: 
466:   // Floor clamp: no dimension weight should go below 0.01
467:   adjusted.altitude = Math.max(0.01, adjusted.altitude);
468:   adjusted.driveHealth = Math.max(0.01, adjusted.driveHealth);
469:   adjusted.polarity = Math.max(0.01, adjusted.polarity);
470:   adjusted.shadowTopology = Math.max(0.01, adjusted.shadowTopology);
471:   adjusted.transformationReadiness = Math.max(0.01, adjusted.transformationReadiness);
472: 
473:   // Normalise to sum to 1.0
474:   const total = adjusted.altitude + adjusted.driveHealth + adjusted.polarity
475:     + adjusted.shadowTopology + adjusted.transformationReadiness;
476: 
477:   if (total <= 0) {
478:     // Safety: if adjustments produced all-zero/negative, return defaults
479:     return { ...DEFAULT_CCI_WEIGHTS };
480:   }
481: 
482:   return {
483:     altitude: adjusted.altitude / total,
484:     driveHealth: adjusted.driveHealth / total,
485:     polarity: adjusted.polarity / total,
486:     shadowTopology: adjusted.shadowTopology / total,
487:     transformationReadiness: adjusted.transformationReadiness / total,
488:   };
489: }
490: 
491: // ---------------------------------------------------------------------------
492: // Session signal derivation
493: // ---------------------------------------------------------------------------
494: 
495: /**
496:  * Select the recommended session theme based on dimensional analysis.
497:  * Priority-ordered: active transformation > post-transformation > critical shadow >
498:  * severe fixation > imminent transformation > polarity momentum > growth-edge >
499:  * consolidation > balanced-development.
500:  */
501: export function selectSessionTheme(
502:   dimensions: Record<string, number>,
503:   inputs: CCIDimensionInputs,
504: ): SessionTheme {
505:   // Active transformation overrides all
506:   if (inputs.transformationReadiness.pendingTransformation) return 'active-transformation';
507: 
508:   // Post-transformation recovery (first 5 sessions after transition)
509:   if (inputs.transformationReadiness.sessionsSinceLastTransformation < 5) return 'post-transformation';
510: 
511:   // Critical shadow pressure demands attention
512:   if (inputs.shadowTopology.maxSeverity > 0.8 || inputs.shadowTopology.compoundPatternCount >= 3) {
513:     return 'shadow-integration';
514:   }
515: 
516:   // Severe drive fixation demands rebalancing
517:   if (inputs.driveHealth.maxFixationRisk > 0.7) return 'drive-rebalancing';
518: 
519:   // Imminent transformation: prep mode
520:   if (inputs.transformationReadiness.linesAtEdge >= 5 && inputs.transformationReadiness.catalystSaturation > 0.7) {
521:     return 'transformation-prep';
522:   }
523: 
524:   // High polarity momentum: deepen
525:   if (inputs.polarity.crystallizationIndex > 0.7 && inputs.polarity.masterMode === 'crystallizing') {
526:     return 'polarity-deepening';
527:   }
528: 
529:   // High altitude with low spread: push the growth edge
530:   if (dimensions['altitude'] > 0.5 && inputs.altitude.spread < 0.15) {
531:     return 'growth-edge-push';
532:   }
533: 
534:   // High altitude with high spread: consolidate
535:   if (dimensions['altitude'] > 0.5 && inputs.altitude.spread > 0.25) {
536:     return 'consolidation';
537:   }
538: 
539:   return 'balanced-development';
540: }
541: 
542: /**
543:  * Compute intensity budget: how much intensity the session can sustain.
544:  * Capped by the weakest link (drive health or shadow state) with a base
545:  * boost from altitude.
546:  */
547: export function computeIntensityBudget(dimensions: Record<string, number>): number {
548:   const healthFloor = Math.min(
549:     dimensions['driveHealth'] ?? 1,
550:     dimensions['shadowTopology'] ?? 1,
551:   );
552:   const altitudeFactor = 0.4 + ((dimensions['altitude'] ?? 0) * 0.3);
553:   return clamp(healthFloor * 0.6 + altitudeFactor * 0.4);
554: }
555: 
556: /**
557:  * Classify shadow pressure level from topology input thresholds.
558:  */
559: export function classifyShadowPressure(input: ShadowTopologyInput): ShadowPressureLevel {
560:   if (input.maxSeverity > 0.8 || input.compoundPatternCount >= 3) return 'critical';
561:   if (input.unresolvedCount > 6 || input.maxSeverity > 0.5) return 'high';
562:   if (input.unresolvedCount > 3 || input.averageSeverity > 0.3) return 'moderate';
563:   return 'low';
564: }
565: 
566: /**
567:  * Classify transformation proximity from readiness input.
568:  */
569: export function classifyTransformationProximity(input: TransformationReadinessInput): TransformationProximity {
570:   if (input.pendingTransformation) return 'active';
571:   if (input.linesAtEdge >= 5 && input.catalystSaturation > 0.7) return 'imminent';
572:   if (input.linesAtEdge >= 3) return 'approaching';
573:   return 'distant';
574: }
575: 
576: /**
577:  * Identify which drive most needs rebalancing exercise.
578:  * Returns the COMPLEMENT of the most imbalanced/fixated drive.
579:  */
580: export function identifyRebalancingTarget(input: DriveHealthInput): Drive | null {
581:   const candidates = ALL_DRIVES
582:     .filter(d => Math.abs(input.balance[d]) > 0.4 || input.fixationRisk[d] > 0.5)
583:     .sort((a, b) => input.fixationRisk[b] - input.fixationRisk[a]);
584: 
585:   if (candidates.length === 0) return null;
586: 
587:   // Return the COMPLEMENT of the over-expressed/fixated drive
588:   const overExpressed = candidates[0];
589:   const complementMap: Record<Drive, Drive> = {
590:     'Agency': 'Communion',
591:     'Communion': 'Agency',
592:     'Eros': 'Agape',
593:     'Agape': 'Eros',
594:   };
595:   return complementMap[overExpressed];
596: }
597: 
598: /**
599:  * Derive polarity session guidance based on master polarity mode.
600:  * Controls diversity of polarity textures and temptation (counter-polarity)
601:  * challenge frequency within the session.
602:  */
603: export function derivePolarityGuidance(input: PolarityInput): PolaritySessionGuidance {
604:   switch (input.masterMode) {
605:     case 'exploration':
606:       return {
607:         mode: 'exploration',
608:         recommendedDiversity: 0.9,
609:         temptationFrequency: 0.0,
610:       };
611:     case 'crystallizing':
612:       return {
613:         mode: 'crystallizing',
614:         recommendedDiversity: 0.4,
615:         temptationFrequency: 0.15 + (0.35 * input.crystallizationIndex),
616:       };
617:     case 'crystallized':
618:       return {
619:         mode: 'crystallized',
620:         recommendedDiversity: 0.2,
621:         temptationFrequency: 0.1,
622:       };
623:   }
624: }
625: 
626: /**
627:  * Derive all session signals from normalised dimensions and raw inputs.
628:  */
629: function deriveSessionSignals(
630:   dimensions: Record<string, number>,
631:   inputs: CCIDimensionInputs,
632: ): CCISessionSignals {
633:   const recommendedTheme = selectSessionTheme(dimensions, inputs);
634:   const intensityBudget = computeIntensityBudget(dimensions);
635:   const shadowPressure = classifyShadowPressure(inputs.shadowTopology);
636:   const transformationProximity = classifyTransformationProximity(inputs.transformationReadiness);
637:   const driveRebalancingTarget = identifyRebalancingTarget(inputs.driveHealth);
638:   const polarityGuidance = derivePolarityGuidance(inputs.polarity);
639: 
640:   return {
641:     recommendedTheme,
642:     intensityBudget,
643:     shadowPressure,
644:     transformationProximity,
645:     driveRebalancingTarget,
646:     polarityGuidance,
647:   };
648: }
649: 
650: // ---------------------------------------------------------------------------
651: // Main entry point
652: // ---------------------------------------------------------------------------
653: 
654: /**
655:  * Compute the Cumulative Consciousness Index from a SignificatorSnapshot.
656:  *
657:  * Pure function: same input always produces same output. No side effects.
658:  * All dimensions are normalised to [0.0, 1.0]. Weights always sum to 1.0.
659:  */
660: export function computeCCI(snapshot: SignificatorSnapshot): CCIScore {
661:   // 1. Extract inputs from Significator snapshot
662:   const inputs = extractDimensionInputs(snapshot);
663: 
664:   // 2. Normalise each dimension to [0, 1]
665:   const dimensions = {
666:     altitude: normaliseAltitude(inputs.altitude),
667:     driveHealth: normaliseDriveHealth(inputs.driveHealth),
668:     polarity: normalisePolarity(inputs.polarity),
669:     shadowTopology: normaliseShadowTopology(inputs.shadowTopology),
670:     transformationReadiness: normaliseTransformationReadiness(inputs.transformationReadiness),
671:   };
672: 
673:   // 3. Adjust weights based on state
674:   const weights = adjustWeights(DEFAULT_CCI_WEIGHTS, inputs);
675: 
676:   // 4. Compute weighted composite
677:   const composite = clamp(
678:     dimensions.altitude * weights.altitude +
679:     dimensions.driveHealth * weights.driveHealth +
680:     dimensions.polarity * weights.polarity +
681:     dimensions.shadowTopology * weights.shadowTopology +
682:     dimensions.transformationReadiness * weights.transformationReadiness
683:   );
684: 
685:   // 5. Identify dominant dimension (highest weighted contribution)
686:   const contributions: { key: keyof CCIWeights; value: number }[] = [
687:     { key: 'altitude', value: dimensions.altitude * weights.altitude },
688:     { key: 'driveHealth', value: dimensions.driveHealth * weights.driveHealth },
689:     { key: 'polarity', value: dimensions.polarity * weights.polarity },
690:     { key: 'shadowTopology', value: dimensions.shadowTopology * weights.shadowTopology },
691:     { key: 'transformationReadiness', value: dimensions.transformationReadiness * weights.transformationReadiness },
692:   ];
693:   contributions.sort((a, b) => b.value - a.value);
694:   const dominantDimension = contributions[0].key;
695: 
696:   // 6. Derive session signals
697:   const sessionSignals = deriveSessionSignals(dimensions, inputs);
698: 
699:   return { composite, dimensions, weights, dominantDimension, sessionSignals };
700: }
701: 
702: // ---------------------------------------------------------------------------
703: // Utility
704: // ---------------------------------------------------------------------------
705: 
706: function clamp(value: number, min = 0.0, max = 1.0): number {
707:   return Math.max(min, Math.min(max, value));
708: }

